import{_ as l,o as t,c as n,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Enhancing Observability and Monitoring for Large Ceph Clusters at Scale - Filipp Akinfiev, Clyso","description":"","frontmatter":{"title":"Enhancing Observability and Monitoring for Large Ceph Clusters at Scale - Filipp Akinfiev, Clyso","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","Observability","Monitoring","Distributed Storage","Scale-Out"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Enhancing_Observability_and_Monitoring_for_Large_Ceph_Clusters_at_Scale_-_Filipp_Akinfiev_Clyso.md","filePath":"posts/2025/Enhancing_Observability_and_Monitoring_for_Large_Ceph_Clusters_at_Scale_-_Filipp_Akinfiev_Clyso.md","lastUpdated":1780459816000}'),e={name:"posts/2025/Enhancing_Observability_and_Monitoring_for_Large_Ceph_Clusters_at_Scale_-_Filipp_Akinfiev_Clyso.md"};function o(s,i,a,_,p,g){return t(),n("div",null,[...i[0]||(i[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>: 提高大规模Ceph集群的观测性和监控能力，特别是针对RADOS网关（RGW）。</p><p><strong>主讲人</strong>: Philip Akinfiev</p><p><strong>会议内容总结</strong>:</p><ol><li><p><strong>观测性的基本概念</strong>:</p><ul><li>观测性是通过收集日志、指标和事件等信息，帮助理解系统工作方式并进行改进的能力。</li><li>观测性有助于提升用户体验、帮助开发者理解集群性能、优化组件间通信，以及通过警报系统处理问题。</li></ul></li><li><p><strong>当前问题</strong>:</p><ul><li>传统观测性方法收集大量数据，但数据冗余，难以找到有用信息。</li><li>数据量过大导致存储、传输和聚合成本高，且在问题发生时，过多的噪声使得问题排查困难。</li></ul></li><li><p><strong>解决方案</strong>:</p><ul><li>提出减少不必要的数据收集，仅收集与业务需求相关的数据。</li><li>采用事件驱动设计（Event Driven Design），通过解耦的方式实现数据的灵活处理和分析。</li></ul></li><li><p><strong>架构设计</strong>:</p><ul><li>提出四层架构： <ol><li><strong>本地生产者（Nearby Producer）</strong>: 直接从Ceph组件或RGW组件中获取数据。</li><li><strong>远程生产者（Remote Producer）</strong>: 通过RESTful API等方式从外部获取数据。</li><li><strong>数据流处理层（Nuts）</strong>: 类似于Kafka的消息队列，负责数据的传输和存储。</li><li><strong>消费者（Consumers）</strong>: 根据业务需求处理数据，如实时监控、日志分析、安全审计等。</li></ol></li></ul></li><li><p><strong>优势</strong>:</p><ul><li><strong>快速查询</strong>: 只处理相关数据，提高查询速度。</li><li><strong>数据管理</strong>: 减少不必要的数据存储，降低成本。</li><li><strong>灵活性</strong>: 可以根据需求动态调整数据收集和处理方式。</li><li><strong>成本效益</strong>: 减少数据量，降低存储和处理成本。</li></ul></li><li><p><strong>当前进展</strong>:</p><ul><li>已在Kubernetes环境中进行了初步测试，结果表明Nuts能够处理大量消息，且数据量显著减少。</li><li>面临的问题是如何在不降低集群性能的情况下，高效地收集和处理数据。</li></ul></li><li><p><strong>未来计划</strong>:</p><ul><li>探索AI模型在观测性中的应用，帮助自动识别和解决问题。</li><li>考虑在Ceph和RGW中实现原生的事件支持，以便更灵活地配置和处理数据。</li></ul></li><li><p><strong>讨论与反馈</strong>:</p><ul><li>与会者讨论了当前RGW的观测性支持，特别是Kafka和HTTP bucket notification的局限性。</li><li>建议未来可以实现更细粒度的数据收集配置，减少对RGW性能的影响。</li></ul></li></ol><p><strong>决定事项</strong>:</p><ul><li>继续推进事件驱动设计的实现，特别是在Kubernetes环境中的应用。</li><li>探索AI模型在观测性中的应用，提升问题识别和解决的效率。</li><li>研究如何在Ceph和RGW中实现更灵活的原生事件支持。</li></ul><p><strong>后续行动计划</strong>:</p><ul><li>完成Nuts在Kubernetes环境中的进一步测试。</li><li>提出在Ceph和RGW中实现原生事件支持的提案。</li><li>探索AI模型在观测性中的应用场景。</li></ul>',9)])])}const d=l(e,[["render",o]]);export{c as __pageData,d as default};
